  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (238::BIGINT, 'Profesor buena nota, explica horrible y tiene 0 Don para pedagogía. Si ve que el estudiante es consistente puede que lo ayude, pero no recomiendo sus clases, pocas veces se da a entender'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo']::TEXT[], '2026-07-25T00:00:00+00:00'::TIMESTAMPTZ, '775c3dce6d17ffbe7f9467f5f5e92d5f9a99e011d8b1543156e4d25cd4e9a3c4'::TEXT, ARRAY[1835]::BIGINT[]),
    (238::BIGINT, 'Vaque se ha puesto la 10 este semestre, dejó bastante práctica para los exámenes y eran idénticas a los exámenes, lo vital con él es siempre ir a consulta, realmente es un buen profe y si le pides ayuda tiene toda la paciencia de explicar las veces que sean necesarias para que el tema quede claro.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2025-11-29T00:00:00+00:00'::TIMESTAMPTZ, 'c8c4e0646921f1849897924772e0ae70bfc3f1db3fad8d25c2dcbd99bc87d4fc'::TEXT, ARRAY[926]::BIGINT[]),
    (238::BIGINT, 'Este mae no es profesor, es ingeniero, son cosas muy distintas, de todos mis años en el TEC este sin duda ha sido el peor profesor que he tenido por lejos, si tienen la oportunidad de matricular con él desaprovéchenla, a menos que sólo lleven ese curso "pesado" y a veces ni así, mejor estudie sólo'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2025-07-21T00:00:00+00:00'::TIMESTAMPTZ, '536f0eb11fac847d23a76f9e85cb48230feee4a49bf7681215a99bf45bfc4aaf'::TEXT, ARRAY[925, 941, 926, 942, 974]::BIGINT[]),
    (238::BIGINT, 'llevar con vaquegod es un canon event, no importa cuánto estudie, los ejercicios de los exámenes nunca van a parecerse a los del libro, vaya mucho a consulta y aprenda a rascar puntos, así pasamos todos :(. puede ser MUY concho con las evaluaciones.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-11-18T00:00:00+00:00'::TIMESTAMPTZ, '586751f495f193f7407400f9f718f9e5f5523c8c88a4d63142699c227f05a3ac'::TEXT, ARRAY[942]::BIGINT[]),
    (238::BIGINT, 'Para el lab el profe lo hace muy fácil, casi no deja tareas, eso sí, cuando deja tareas lo hace de la nada y a veces ni el mismo sabe resolverlas. El curso es fácil y no demanda mucho tiempo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2023-07-14T00:00:00+00:00'::TIMESTAMPTZ, 'ff3c2904212322a453078611ff2d90d05bdb44f5869c7f21836009349d56f44d'::TEXT, ARRAY[958]::BIGINT[]),
    (238::BIGINT, 'El Vaque siendo Vaque. Usted no va a aprender nada, con costos si le va a entender algo. Los examenes no importa lo que se ve en clase, se los saca de no se donde antes de la clase. Hace labs dónde la preparación es nula y el curso como tal no tiene. Es todo un caso este mae, no lo recomiendo.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2023-06-25T00:00:00+00:00'::TIMESTAMPTZ, '1a4bf5cf4611cb7398afeb9ba81b757ef91c2033135a14a183687de4950deb21'::TEXT, ARRAY[974]::BIGINT[]),
    (238::BIGINT, 'Los examenes no se parecen a lo visto en clase, no sabe explicar, ni el mismo sabe como resolver los ejemplos de clase.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('10','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, '0066d2ba60ed2d9fd89089b521446f2039e48300931dc245dd38b10c9bba7aa1'::TEXT, ARRAY[3053]::BIGINT[]),
    (238::BIGINT, 'Nunca me puse el cinturón manejando a la clase por las ganas de matarme antes de llegar a recibirla'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2023-06-17T00:00:00+00:00'::TIMESTAMPTZ, '762b748341f6fcaaf6cd848161a948d409fa0e71649cc1cbb24bf8d76e89e00e'::TEXT, ARRAY[3053]::BIGINT[]),
    (238::BIGINT, 'se nota que quiere enseñar y sabe la importanica de este curso para nuestras vidas así como todos los aspectos del curso solo quiere que estudien y mas que aprendan'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Muchas tareas']::TEXT[], '2023-04-21T00:00:00+00:00'::TIMESTAMPTZ, 'a6e4085f4483b08e519b0240ccae1122a70a161219561919556b8999f10eddc5'::TEXT, ARRAY[3053]::BIGINT[]),
    (238::BIGINT, 'Con este mae no hay remedio, se pasa fácil, pero no se aprende nada'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'f0a61359f16a6e9f2010e91bef4d32ae926461dfb547ee1dd4d19141012f8a2b'::TEXT, ARRAY[974]::BIGINT[]),
    (238::BIGINT, 'El profe es terrible, explica mal y a veces califica duro. Es mejor estudiar solo y después ver las clases en 2x porque no son muy útiles, la verdad no se aprende mucho pero no es difícil pasar'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura']::TEXT[], '2021-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'b3099bfecfe36cc4d674674be82ccfe1739cfe4f74015d81cfa03acb292028c6'::TEXT, ARRAY[3053]::BIGINT[]),
    (238::BIGINT, 'Es un curso que casi se pasa desde que matricula. No se la crea tampoco, hay que estudiar y repasar los videos antes de examen. El profe hace tareas y quices que explica durante la clase y las sesiones de consulta son muy provechosas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'e782dd1297179a61281317dcb5cf972af61f691a96dcf89b4e257b0325dabcb3'::TEXT, ARRAY[974]::BIGINT[]),
    (238::BIGINT, 'El curso con el es fácil pero sea muy muy detallado en la solución de los parciales con cada paso realizado para que no le baje puntos.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-11T00:00:00+00:00'::TIMESTAMPTZ, '0f413d55efe35747a27961f41311c20437415cf12d4e94cafd605b2b415b24ad'::TEXT, ARRAY[974]::BIGINT[]),
    (238::BIGINT, 'Literalmente da toda la información para tareas o exámenes en bandeja, pero solo si presta atención a los vídeos. Ayuda demasiado en tareas, es buen profe, pero las evaluaciones si se toma su tiempo.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Muchos proyectos grupales']::TEXT[], '2021-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'd51c716e08f7faed2dd1b6a557dde8da6551870b3572b7ee5a592fc7085a49fc'::TEXT, ARRAY[974]::BIGINT[]),
    (238::BIGINT, 'Clases eternas y tediosas, ayuda mucho en consulta, deja evaluaciones que muchas veces ni él ha resuelto entonces se vuelven confusas hasta cierto punto que él tiene que reestructurar el ejercicio para que tenga solución. Irresponsable con las fechas y horario de las evaluaciones.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos']::TEXT[], '2021-01-25T00:00:00+00:00'::TIMESTAMPTZ, '08e9015dd2a29b79d6022cb79f8ff760460f6f76a62853694b72fdb987105860'::TEXT, ARRAY[974]::BIGINT[]),
    (238::BIGINT, 'Usted entiende bastante, pero siente que no esta aprendiendo tanto si no lee los libros de referencia. Pero es facil de pasar el curso.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, 'fd7ba5749ba80316bd4b9689375889a3300b0e31b43d11eba11ae56f2573d4fa'::TEXT, ARRAY[3053]::BIGINT[]),
    (238::BIGINT, 'Buen profe vaya a consulta para los trabajos que deje, ayuda mucho.Graba las clases ayuda mucho. El curso es muy teorico casi nada de calculo y para el virtual hagarrele cariño Orcad a el profe le gusta este simulador.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Muchos proyectos grupales']::TEXT[], '2020-08-21T00:00:00+00:00'::TIMESTAMPTZ, '49c14f1f53dd02303c57c39c8ed8fec3b5ce0af7bf02deacb5facb85b057fe3c'::TEXT, ARRAY[3053]::BIGINT[]),
    (238::BIGINT, 'Mucho mejor en virtual. Todos los trabajos en grupo.Ayuda bastante en consulta. Varias recomendaciones: 1) No vaya a la clase( aburridas) y después ve el vídeo a su ritmo o con otra velocidad. 2) No explica los conceptos básicos, búsquelos por aparte y se le va a hacer más fácil.Use vídeos no libros'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, 'd13555332f1e08c6da3b149a1d00fcb8d567db2fc00d72ff81200d45ec1395a8'::TEXT, ARRAY[974]::BIGINT[]),
    (238::BIGINT, 'Lo recomiendo solo si es virtual porque todo es grupal. El profe explica regular y muy a su manera, no se basa en ningún libro y para estudiar son solo los apuntes y lo que él dice en clases. En consulta sí ayuda mucho pero sí es tedioso su forma de dar la materia.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, '65ae5a2b1aa761effd87f8cae701a63a8340b21ac970820c28a5bbfe09a31694'::TEXT, ARRAY[974]::BIGINT[]),
    (238::BIGINT, 'En virtual explica mucho mejor que presencial. Él explica lo básico y depende de uno entenderlo bien para aplicarlo en los examenes. Ayuda un montón en consulta. Si usted pone atención y va a consulta puede aprender bastante. No tiene ningún libro de referencia y la materia la da muy a su manera.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-19T00:00:00+00:00'::TIMESTAMPTZ, 'd0386ac0b07ace9229798abace0bbc58664d5d07b1082e81061e816d3dfeb1b9'::TEXT, ARRAY[974]::BIGINT[]),
    (238::BIGINT, 'Solo lo recomiendo si es virtual, ya que hay videos y bastantes trabajos grupales, entonces puede resultar relativamente fácil. No explica todo tan claro como uno quisiera, pero en consulta sí ayuda. Si llevó CC y CA con él, llevar máquinas no es tan malo en comparación...'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-14T00:00:00+00:00'::TIMESTAMPTZ, 'ca64786d8fbc974d7c8839d06704f6ec3784d17e8044f329bb0ced5e7c3076a8'::TEXT, ARRAY[3053]::BIGINT[]),
    (238::BIGINT, 'Virtual: Weno no hay otra opción. Graba las clases y eso ayuda porque en vivo no se entiende tan bien. Un poco desordenado con la evaluación Examenes y tarea en grupos Yo aprovecharía la modalidad virtual, se puede aprender poquito y pasa de fijo'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-07-30T00:00:00+00:00'::TIMESTAMPTZ, '21a8ca622fb5d9362c7efb7042eb48917438227519600c6fe31955afb6b63ca9'::TEXT, ARRAY[974]::BIGINT[]),
    (238::BIGINT, 'ES EL PEOR PROFE, DESORDENADO, SE SACA LAS EVALUACIONES DEL CnL0, EN SERIO NO SE APRENDE NADA Y SI UNO QUIERE LEER Y APRENDER POR APARTE, LO QUE EL DA EN CLASE ES INSUFICIENTE PARA ENTENDER.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2020-07-18T00:00:00+00:00'::TIMESTAMPTZ, '494aef986fabcfd8d643119f4cfdbcc365563f0fbce72faa0f72bdc4a9a65634'::TEXT, ARRAY[974]::BIGINT[]),
    (238::BIGINT, 'No es lo mejor entre los profes, pero tampoco es lo peor. El problema es que este curso pretende que la gente aprenda dos tipos de circuitos en un solo semestre, donde otras carreras las llevan por separado. Tip: Impriman las presentaciones del mae, antes de ir a clases.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2020-02-08T00:00:00+00:00'::TIMESTAMPTZ, '7bb6ca27e8ce10863fa30647861d303bde01d42677cbe85da80de381b1424c21'::TEXT, ARRAY[3049]::BIGINT[]),
    (238::BIGINT, 'De los peores profes del TEC,explica muy confuso y habla muy bajo.Había que correr para agarrar campo adelante.Dejaba tareas rarísimas, una fue imposible de resolver.Las presentaciones con las que explica solo traen imágenes así que si no apuntas no sirven para estudiar.Examenes difíciles y largos.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2019-12-07T00:00:00+00:00'::TIMESTAMPTZ, '12eadf1c10c27fefc56f83c4cbf4afa85e7de4d371575177c8c5cdccf6d45ac7'::TEXT, ARRAY[3049]::BIGINT[]),
    (238::BIGINT, 'Hace todo a como le da la gana. La parte de CA la ve como a él se le ocurre y no como viene en ningún libro de texto. Aprendí más no llegando a clases que yendo. No esperés aprender nada si lo lleva con él. Pro tip: si sos de los de física puede que le caigás mejor.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Muchos exámenes']::TEXT[], '2019-12-02T00:00:00+00:00'::TIMESTAMPTZ, '7b44949a586bc117643a756f16029a99efefc802146e51752e88f86eac620ce7'::TEXT, ARRAY[3049]::BIGINT[]),
    (238::BIGINT, 'Lo único que criticaría es que en la mayoría de clases va muy rápido, entonces a veces uno no sabe si copiar o poner atención. Pero no me parece mal profe, él explica las veces que sea necesario. En consulta es muy bueno.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2019-11-30T00:00:00+00:00'::TIMESTAMPTZ, '80e8f5290f21e3f3ddd8e137bd41ac93fae54a26eb47c76da9ce81fad9f88dca'::TEXT, ARRAY[926]::BIGINT[]),
    (238::BIGINT, 'El profesor deja demasiado que desear, si matricula con el su mejor opción es ir a tutorías. La clave está en ponerle demasiado a los primeros dos exámenes y no aflojar en los dos últimos. El profesor busca ayudar a los estudiantes. La asistencia no es obligatoria pero es recomendable.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-28T00:00:00+00:00'::TIMESTAMPTZ, '8a6badab195b2555a8ef713650d5050eb7dd6376885be1b9e1a6fb1db85629f9'::TEXT, ARRAY[3049]::BIGINT[]),
    (238::BIGINT, 'Poniéndolo simplemente: NO matricule con él. Casi no se esfuerza por explicar bien la materia, y las presentaciones que usa son muy confusas para repasar. Si va a tutorías y lleva la materia al día, sin embargo, es posible pasar a la primera... Mejor no se arriesgue.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2019-11-22T00:00:00+00:00'::TIMESTAMPTZ, '17769f719194da4f53c9bfb7fde675ee346a621363cce4697e2d225d71547df3'::TEXT, ARRAY[3049]::BIGINT[]),
    (238::BIGINT, 'No es para nada un buen profesor, explica muy confuso, las presentaciones no traen la materia y están desordenadas, se atrasa con las evaluaciones, la materia de entiende hasta que la explica el profesor de tutorías.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2019-11-17T00:00:00+00:00'::TIMESTAMPTZ, '791f7519b6fdca2c5993885d654fcce87e3b7a98f983058f537bac41f7078b04'::TEXT, ARRAY[3049]::BIGINT[]),
    (238::BIGINT, 'Creo que este profesor deberia pensar muy bien en la automorision porque que clase mas dificil. Acabo de hacer un quiz con cosas que ni nos enseño.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Exámenes retadores']::TEXT[], '2019-08-29T00:00:00+00:00'::TIMESTAMPTZ, '7acc9efd3e5bcfb90e069d9901222b56ae7be956c2828cf8b6ec18efff268847'::TEXT, ARRAY[3049]::BIGINT[]),
    (238::BIGINT, 'Tiende a enredarse o sacar datos al azar para explicar algún ejemplo, pero se esfuerza por explicar y repite las veces que sea necesario. Es muy importante ir a consulta ya que ahí atiende más puntual las dudas que uno tenga además de ser necesario el brinda ayuda'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2019-07-20T00:00:00+00:00'::TIMESTAMPTZ, '4a336a014c19b76ae5f12c70f13160579784e2c1b643752dd0edaa778e7bb930'::TEXT, ARRAY[3049]::BIGINT[]),
    (238::BIGINT, 'El profe sabe mucho y uno le puede sacar provecho al curso. Revisó todo al final del semestre y muy fácil. El curso no se hace pesado.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'f918bdd3162d5857dfe4b142e96cb0157ffd060d3d7c04d681cce0450beb4285'::TEXT, ARRAY[941]::BIGINT[]),
    (238::BIGINT, 'No es muy claro a la hora de explicar, y si usted es una persona que se distrae fácilmente, es casi imposible seguirle el hilo en clase. Sin embargo, da muchas oportunidades de recuperar puntos. La clave para pasar con él llevar muy al día la materia.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2019-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'd7420b807aa83c940ccb1811508947fc0e89506149b9effabb76502ac05d11ce'::TEXT, ARRAY[3049]::BIGINT[]),
    (238::BIGINT, 'No sé por qué la gente no quiere al tío Vaque, es demasiado buena gente, en clase es muy enredado y va rápido, pero se le entiende, ayuda mucho con los trabajos, los exámenes son muy parecidos a hechos anteriormente y en consulta espera lo que sea hasta que uno entienda.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-12T00:00:00+00:00'::TIMESTAMPTZ, '0af99612dde61d922cfbb868526f7e439816532f3d6018dd1451659f098f8097'::TEXT, ARRAY[926]::BIGINT[]),
    (238::BIGINT, 'Sabe mucho, pero no explica nada. Espera que usted ya lo sepa todo, se salta temas, califica duro y ES DESORDENADO. No lo recomiendo.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2019-02-10T00:00:00+00:00'::TIMESTAMPTZ, 'ab0f7c51ac5afa837daac223c91f5b9409192ee990cb25404f78747d47b317b9'::TEXT, ARRAY[926]::BIGINT[]),
    (238::BIGINT, 'El profe es un poco confuso, cuesta seguirle el ritmo en la clase, pero en consulta es muy bueno, ayuda muchísimo. Califica normal y sí es muy estricto con la hora de entregar los trabajos.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2019-01-15T00:00:00+00:00'::TIMESTAMPTZ, 'a6f43e8717661ca41fc70ab4aa92c08fc54e2d21f7c01215eb049c74d655f135'::TEXT, ARRAY[925]::BIGINT[]),
    (238::BIGINT, 'Un poco desordenado en cuanto a la entrega de las evaluaciones, a veces revisa fácil a veces no.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-12-28T00:00:00+00:00'::TIMESTAMPTZ, '7f15f0123130f1da8cc07c4cc9b079cfacff6dbcb8f79e1ea50d12b59cf62581'::TEXT, ARRAY[925, 958]::BIGINT[]),
    (238::BIGINT, 'Un criminal. Desordenado, improvisa las clases (terminó de dar "teoría" en semana 8-9. Pésima opción pero desgraciadamente suele ser la única.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-12-13T00:00:00+00:00'::TIMESTAMPTZ, '15984688a07aed868e9a8d7a3fa299588bb8c7d8040d8d678033af07908301aa'::TEXT, ARRAY[974]::BIGINT[]),
    (238::BIGINT, 'Guía práctica para aprobar circuitos ( ?° ?? ?°) -Nunca faltar a clase, se puede perder de algún trucazo para examen. - Llevar la materia al día, sin excepción. -El profe explica con mucha paciencia si usted se lo pide, no se quede con la duda. -Haga todos los ejercicios del libro por tema.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador']::TEXT[], '2018-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'ca6b43fe0e8be394e8a053112ee6fe3b1020d13434618688eac95ade2f090e77'::TEXT, ARRAY[3049]::BIGINT[]),
    (238::BIGINT, 'Sus expliciones son malas, se confunde mucho. No es claro con las instrucciones de los informes. El mae habilita la opción de entregar el trabajo dos horas antes de la entrega final, y si usted no se dio cuenta perdió la asignación.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos']::TEXT[], '2018-09-19T00:00:00+00:00'::TIMESTAMPTZ, '433fd06b777702c483cb5e772340f215fab1ab7de6120d02ecf5ffda5929ed54'::TEXT, ARRAY[925]::BIGINT[]),
    (238::BIGINT, 'Excelente persona pero se queda un poco corto como profesor. Genial para repitientes pero si lo va a llevar por primera vez no se confíe. La clase es monótona, habla bajo y escribe pequeño. Se debe ser autodidacta. Ayuda muchísimo si le demuestra interés.'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2018-06-29T00:00:00+00:00'::TIMESTAMPTZ, '18d15a3c3ca806ef501b1ed795cd9fdbfa2b4c1c513b3eb23b29aa18e874e653'::TEXT, ARRAY[3049]::BIGINT[]),
    (238::BIGINT, 'La clase es muy confusa, no explica nada. Si quiere pasar debe ser muy autodidacto, además los ejemplos que realiza o da para praticar no se parecen en nada a los que hace en el examen.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'ff3dd60c384b74d593017e50d5d93415fae618019f179a5aa6ae0f463d629978'::TEXT, ARRAY[926]::BIGINT[]),
    (238::BIGINT, 'Si quiere pasar prepárese para ser autodidacta, el mae hace ejercicios en clases, pero son básicos en comparación con los que entran en los exámenes, además, no son parecidos, por lo que debe tener todo muy claro para saber cómo entrarles. Recomiendo el libro el libro de referencia para la teoría,'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-23T00:00:00+00:00'::TIMESTAMPTZ, '65fbc60b36bbed8c1607d608423611a4cae38bef02a64e99f67cad039cf6e78a'::TEXT, ARRAY[926]::BIGINT[]),
    (238::BIGINT, 'Vaquerano da cursos a nivel de universidad, examenes anti calculadora, ejercicios conceptualmente muy poderosos y por eso es que alguna gente se queja pero en realidad es buen profe, ayuda, distribuye la evaluacion de manera decente y tiene paciencia explicando. Siempre con buena disposicion.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2018-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'ea918e9adcd3dff0ef4b5e556b2c8c8c88058b0cadf129bd3746339a55901e36'::TEXT, ARRAY[925, 941, 958]::BIGINT[]),
    (238::BIGINT, 'Una peste... Los informes no se pueden hacer porque las instrucciones no son claras. No prepara las clases, llega a improvisar. Ahh y hay que estar corriendo al final porque es demasiado desordenado y se le olvida hacer las evaluaciones correspondientes. En resumen, un chiste.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Muchos proyectos grupales']::TEXT[], '2018-01-25T00:00:00+00:00'::TIMESTAMPTZ, 'fcb9ffddb657c7f4fb8467a37e25e55eb9f0ebaf0fef7611d1183983e55c495c'::TEXT, ARRAY[925, 958]::BIGINT[]),
    (238::BIGINT, 'No explica bien y avanza demasiado rápido pero si ayuda mucho al estudiante, si va a repetir el curso este profe es el ideal, si lo va a llevar por primera vez va a tener que ser autodidacta'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Aspectos de calificación claros', 'Exámenes retadores']::TEXT[], '2017-12-04T00:00:00+00:00'::TIMESTAMPTZ, '57332343aaa4ac39e84476e6ea729c55c7f9e40627206bb9b66453bfd3ccd9e4'::TEXT, ARRAY[3049]::BIGINT[]),
    (238::BIGINT, 'casi que hay que ser autodidacta pero ayuda mucho en consulta y si uno estudia del libro le va bien'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-18T00:00:00+00:00'::TIMESTAMPTZ, '145384d4e7e71975aae723ed741d85385db9353c320e1ea44c82ec0244323263'::TEXT, ARRAY[3049]::BIGINT[]),
    (238::BIGINT, 'Tiene mala fama, pero yo matricularía con él de nuevo. Si usted estudia con tiempo y en grupo, lee el libro y va a consulta con él, si se puede pasar circuitos a la primera! Nada más es de ponerle mucho! Excelente persona!'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-13T00:00:00+00:00'::TIMESTAMPTZ, '2ed0d0dc6a6fa7999b0ede21e32fbbb0b68bd8687f1e6568849757bc58d2fb07'::TEXT, ARRAY[3049]::BIGINT[]),
    (238::BIGINT, 'Malo explicando, ayuda mucho en consulta, ayuda con la nota si ve que uno sí le puso. El problema es que los examenes los hace con el otro profe y califican cosas que no se vieron en clase o que no se les dio importancia. hay que estudiar mucho del libro y en grupos.'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-07T00:00:00+00:00'::TIMESTAMPTZ, 'f089343613fef8b52ae73beccbf2efb32510f43fb86b772147696001ef6bb1ca'::TEXT, ARRAY[3049]::BIGINT[]),
    (238::BIGINT, 'El problema aquí es la fama del hombre. Si usted le pone, lee el libro, va a consulta y estudia con tiempo y en grupo, pasa. Sí, a la primera. Es una gran persona, busca ayudar, no es tan malo como dicen. Ponga de su parte. No explica muy bien y las evaluaciones son duras, eso si.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-12-10T00:00:00+00:00'::TIMESTAMPTZ, '9175caaa65b6616154e131417a07a03f45cd391b28b73a71b3263f7e157f93a8'::TEXT, ARRAY[3049]::BIGINT[]),
    (238::BIGINT, 'Todos dicen que es malo, pero me pareció muy bueno por lo menos para Lab explica bastante bien, y si en no entiende algo vaya a consulta y ya. Para Lab lo recomiendo bastante'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'f352708db506a5582336be6fe9777e8494862acccb0ef192d6de1026d6db382a'::TEXT, ARRAY[941]::BIGINT[]),
    (238::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2016-06-27T00:00:00+00:00'::TIMESTAMPTZ, '7910eee99b05adb43fbeded78559e7f705d8154fc9ece3632e836d6092d278cc'::TEXT, ARRAY[3049]::BIGINT[]),
    (238::BIGINT, 'El mae es muy buena persona, ayuda mucho, vaya a consulta y pídale ayuda en las notas xD. Los exámenes son los mismos de semestres pasados, estúdielos!'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-22T00:00:00+00:00'::TIMESTAMPTZ, '6232cd764320765b4e5a6cd4b417ef1651d1229dcf89c1eadbc17d19053f78b1'::TEXT, ARRAY[3049]::BIGINT[]),
    (238::BIGINT, 'No sabe explicar a veces, pero con estudiar los ejercicios que da, los exámenes viejos, y leyendo a conciencia el libro se hace accesible. Como persona, una teja, ayuda mucho.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'e471d3a9d76df85638b9fd6a3c5c8a1b68c9dda8c2622365ee35a4ef3d1191c5'::TEXT, ARRAY[3049]::BIGINT[]),
    (238::BIGINT, 'vuélvase autodidacta, vaya a consulta y estudie exámenes viejos'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-17T00:00:00+00:00'::TIMESTAMPTZ, '2807cac738b7fa787a3a3c6ea56154bad32f79bafc1a53dc939670204c72cb81'::TEXT, ARRAY[3049]::BIGINT[]),
    (238::BIGINT, 'El mae no explica bien, sin embargo es una teja de persona, ayuda mucho en general pero tiene que estudiar bastante, en lo personal recomiendo que estudien con exámenes viejos que prácticamente son copias.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'db34d96d15a2a18e612d8da998e3e56a6b37d3da6d7927335363367bf1cfc00c'::TEXT, ARRAY[3049]::BIGINT[]),
    (238::BIGINT, 'De verdad como persona es excelente, se nota que quiere que uno aprenda pero no se le entiende nada cuando explica.'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'b36909eddcc67b016518cc8a91344427cf6593b91e00ea10d6606e2c30378df5'::TEXT, ARRAY[3049]::BIGINT[]),
    (238::BIGINT, 'Es una buena persona, pero no sabe explicar, asume que uno ya se sabe todo.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-08T00:00:00+00:00'::TIMESTAMPTZ, '38bf2cbc1641201f12480e3731899585a41b85478b550236b41a0e4481051139'::TEXT, ARRAY[3049]::BIGINT[]),
    (238::BIGINT, 'No explica bien, pero es muy buena gente y trata de ayudarlo a uno'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura']::TEXT[], '2016-06-02T00:00:00+00:00'::TIMESTAMPTZ, '68241dd9a3d593be5bfb3c6c456d8bc770706cafd0cfaeeaf679fe9665ab8cf9'::TEXT, ARRAY[3049]::BIGINT[]),
    (238::BIGINT, 'No hay otro :(. Es muy buena persona y lo trata de ayudar a uno. Pero en serio no se le entiende NADAAA!!!'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-29T00:00:00+00:00'::TIMESTAMPTZ, '7afbe61095b81f5138411ad2c51610e30df2d0613b7d99bdcd657bb5f9660ca3'::TEXT, ARRAY[3049]::BIGINT[]),
    (238::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-18T00:00:00+00:00'::TIMESTAMPTZ, '1cc16e9adf12d27972229e919401c9a01e079c172ef1fe560e890f344940ae76'::TEXT, ARRAY[3049]::BIGINT[]),
    (238::BIGINT, 'La verdad es que no explica muy bien, pero en consulta es genial y es buena gente. Las evaluaciones son bastante accesible y entretenidas.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-29T00:00:00+00:00'::TIMESTAMPTZ, '8ac99f640ed8dddcd8e636fc8f4d294663ec2a8fb0c6229ec7accac16b8089a8'::TEXT, ARRAY[974]::BIGINT[]),
    (238::BIGINT, 'Realmente malo.No se si le explica a la clase o a si mismo. Enredado y truculento.Realmente la peor opcion'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('15','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-15T00:00:00+00:00'::TIMESTAMPTZ, '1c39fbdcefc617cbd69030ac8787806a2dae3f2a2e2046c83bdc16b953824391'::TEXT, ARRAY[942]::BIGINT[]),
