    (238::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-17T00:00:00+00:00'::TIMESTAMPTZ, '8ebf136bc28f24d3d2cd871cce31b362df421085f7637ab48b1e1924e5fce7eb'::TEXT, ARRAY[3049]::BIGINT[]),
    (238::BIGINT, 'No hay nada más para escoger'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('30','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-17T00:00:00+00:00'::TIMESTAMPTZ, '40310e4d2d3d3207bbda1b7c509f91a99bb9493e3de9e79bc6efca4daf68fe5c'::TEXT, ARRAY[3049]::BIGINT[]),
    (238::BIGINT, 'Sus exámenes son principalmente copias de pruebas de semestres anteriores, no van muy relacionados con lo abarcado en clase.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('10','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '2c434d69f04b9f3f19537d8dd9623525db16ae8a4588556ce793d403e1ddcbf4'::TEXT, ARRAY[3049]::BIGINT[]),
